[Form]
public class RMarketStrategy extends FormRun 
{

}

/// <summary>
///
/// </summary>
private FormDataSource currentCondition_DS()
{
    FormDataSource ret;
    if (ActionConditionTabPage.isActivePage())
        ret = ActionConditionTable_DS;
    else if (OrdersConditionTabPage.isActivePage())
        ret = OrdersConditionTable_DS;
    return ret;
}

private void buildConditionTree()
{
    RMarketStrategyAction strategyAction = RMarketStrategyAction_DS.cursor();

    ConditionTree.deleteAll();

    if (strategyAction.RecId)
    {
        element.addConditionTreeNodes(
            strategyAction.RecId,
            0,
            FormTreeAdd::Root);
    }
}

private TreeItemIdx addConditionGroupTreeNode(
    RMarketConditionGroup _conditionGroup,
    TreeItemIdx _parentNode)
{
    FormTreeItem treeItem = new FormTreeItem();
    str caption;

    caption = strFmt(
        "%1 %2 (%3)",
        _conditionGroup.ParentRecId ? "▣" : "◆",
        _conditionGroup.Name,
        enum2Str(_conditionGroup.RMarketConditionOperator));

    treeItem.text(caption);
    treeItem.data([
        tableNum(RMarketConditionGroup),
        _conditionGroup.RecId
    ]);

    return ConditionTree.addItem(
        _parentNode,
        0,
        treeItem);
}

private void addConditionTreeNodes(
    RecId       _actionRecId,
    RefRecId    _parentRecId,
    TreeItemIdx _parentIdx)
{
    RMarketConditionGroup conditionGroup;
    RMarketConditionTable condition;
    FormTreeItem          treeItem;
    TreeItemIdx           itemIdx;
    str                   caption;

    // Root events and nested groups
    while select conditionGroup
    order by conditionGroup.Num
    where conditionGroup.RMarketStrategyActionRecId == _actionRecId
       && conditionGroup.ParentRecId == _parentRecId
    {
        itemIdx = element.addConditionGroupTreeNode(
            conditionGroup,
            _parentIdx);

        // Recursively add nested groups and conditions
        element.addConditionTreeNodes(
            _actionRecId,
            conditionGroup.RecId,
            itemIdx);
    }

    // Leaf conditions of the current group
    if (_parentRecId)
    {
        while select condition
        order by condition.Num
        where condition.Relation ==
                RMarketConditionRelation::RMarketConditionGroup
           && condition.RefRecId == _parentRecId
        {
            treeItem = new FormTreeItem();

            treeItem.text(strFmt(
                "● Condition %1",
                condition.Num));

            treeItem.data([tableNum(RMarketConditionTable), condition.RecId]);

            ConditionTree.addItem(
            _parentIdx,
            0,
            treeItem);
        }
    }
}

private void createConditionGroup(TreeItemIdx _parentNode = 0)
{
    RMarketStrategyAction strategyAction = RMarketStrategyAction_DS.cursor();

    RMarketConditionGroup conditionGroup;
    RMarketConditionGroup parentGroup;
    RMarketConditionGroup lastGroup;
    RMarketConditionTable lastCondition;

    FormTreeItem    treeItem;
    TreeItemIdx     newItemIdx;
    container       nodeData;
    TableId         tableId;
    RefRecId        parentRecId = 0;
    int             nextNum;

    if (!strategyAction.RecId)
        return;

    // Resolve parent node
    if (_parentNode)
    {
        treeItem = ConditionTree.getItem(_parentNode);

        if (!treeItem)
            return;

        nodeData = treeItem.data();

        if (conLen(nodeData) != 2)
            return;
        [tableId, parentRecId] = nodeData;
        if (tableId != tableNum(RMarketConditionGroup))
            return;

        parentGroup = RMarketConditionGroup::find(parentRecId);

        if (!parentGroup.RecId ||
            parentGroup.RMarketStrategyActionRecId != strategyAction.RecId)
        {
            throw error("Invalid parent condition group.");
        }
    }

    // Find the next sibling number
    select maxof(Num) from lastGroup
    where lastGroup.RMarketStrategyActionRecId
            == strategyAction.RecId
       && lastGroup.ParentRecId == parentRecId;

    nextNum = lastGroup.Num + 1;

    // Nested groups and conditions share the same order
    if (parentRecId)
    {
        select maxof(Num) from lastCondition
            where lastCondition.Relation == RMarketConditionRelation::RMarketConditionGroup
               && lastCondition.RefRecId == parentRecId;

        if (lastCondition.Num >= nextNum)
        nextNum = lastCondition.Num + 1;
    }

    conditionGroup.clear();
    conditionGroup.RMarketStrategyActionRecId = strategyAction.RecId;
    conditionGroup.ParentRecId = parentRecId;
    conditionGroup.Num = nextNum;
    conditionGroup.RMarketConditionOperator = RMarketConditionOperator::And;
    conditionGroup.Name = parentRecId ? strFmt("Group %1", nextNum) : strFmt("Event %1", nextNum);

    if (!conditionGroup.validateWrite())
        return;

    ttsbegin;
    conditionGroup.insert();
    ttscommit;

    RMarketConditionGroup_DS.research(true);
    RMarketConditionGroup_DS.findRecord(conditionGroup);

    // Add only the new node
    newItemIdx = element.addConditionGroupTreeNode(
        conditionGroup,
        _parentNode ? _parentNode : FormTreeAdd::Root);

    // Expand its parent
    if (_parentNode)
    {
        ConditionTree.expand(
            _parentNode,
            FormTreeExpand::Expand);
    }

    // Select the newly created node
    ConditionTree.select(newItemIdx);
}

private void updateFormDesign()
{
    NodeNewEventButton.enabled(true); // Action in grid selected
    NodeNewGroupButton.enabled(true); // Action in grid selected && root or branch in tree selected
    NodeNewConditionButton.enabled(false); // Action in grid selected && leaf or branch in tree selected
    NodeDeleteButton.enabled(false); // Node in tree selected and hasn't any child
    NodeUpButton.enabled(false); // Node has Num > 1
    NodeDownButton.enabled(false); // Node has Num < max(Num)

    // any changes of elements visibility or enablity must be here
}

/// <summary>
///
/// </summary>
public void init()
{
    super();

    element.updateFormDesign();
}

/// <summary>
///
/// </summary>
/// <param name = "_append"></param>
public void create(boolean _append = false)
{
    RMarketStrategyAction action;

    super(_append);

    select maxof(Num) from action
        where action.StrategyId == RMarketStrategy.StrategyId;

    RMarketStrategyAction record = this.cursor();
    //record.StrategyId = RMarketStrategy.StrategyId;
    record.Num   = action.Num + 1;
}

/// <summary>
///
/// </summary>
/// <returns></returns>
public int active()
{
    int ret = super();

    element.buildConditionTree();
    element.updateFormDesign();

    return ret;
}

/// <summary>
///
/// </summary>
/// <param name = "_append"></param>
public void create(boolean _append = false)
{
    RMarketConditionTable condition;

    super(_append);

    select maxof(Num) from condition
        where condition.RefRecId == ActionConditionTable.RefRecId;

    RMarketConditionTable record = this.cursor();
    //record.RefRecId = RMarketStrategyAction.RecId;
    record.Num   = condition.Num + 1;
    record.Relation = RMarketConditionRelation::RMarketStrategyAction;
    record.Interval = RMarketStrategy.Interval;
    record.SecondInterval = RMarketStrategy.Interval;
}

/// <summary>
///
/// </summary>
/// <param name = "_append"></param>
public void create(boolean _append = false)
{
    RMarketConditionTable condition;

    super(_append);

    select maxof(Num) from condition
        where condition.RefRecId == OrdersConditionTable.RefRecId;

    RMarketConditionTable record = this.cursor();
    //record.RefRecId = RMarketStrategyAction.RecId;
    record.Num   = condition.Num + 1;
    record.Relation = RMarketConditionRelation::RMarketStrategyOrders;
    record.Interval = RMarketStrategy.Interval;
    //record.SecondInterval = RMarketStrategy.Interval;
}

