/// Delete data project
/// </summary>
public void clicked()
{
    RMarketStrategyAction  action;
    super();

    action = RMarketStrategyAction_DS.cursor();
    if (action.RecId && action.validateDelete())
    {
        try
        {
            action.delete();
        }
        catch
        {
            //continue with other records
        }
    }
    RMarketStrategyAction_DS.research();
}

